CREATE TABLE schema_version_v2(version INTEGER PRIMARY KEY CHECK(version IN(1,2)),backend TEXT NOT NULL CHECK(backend='postgres'),checksum TEXT NOT NULL);
INSERT INTO schema_version_v2 SELECT * FROM schema_version;
DROP TABLE schema_version;
ALTER TABLE schema_version_v2 RENAME TO schema_version;
CREATE TABLE capability_assignment_v2(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,capability TEXT NOT NULL CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage')),scope_kind TEXT NOT NULL CHECK(scope_kind IN('org','employee')),scope_id TEXT NOT NULL,employee_id TEXT,PRIMARY KEY(org_id,subject_id,capability,scope_kind,scope_id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),CHECK((scope_kind='org' AND scope_id=org_id AND employee_id IS NULL) OR (scope_kind='employee' AND employee_id IS NOT NULL AND scope_id=employee_id)));
INSERT INTO capability_assignment_v2 SELECT * FROM capability_assignment;
DROP TABLE capability_assignment;
ALTER TABLE capability_assignment_v2 RENAME TO capability_assignment;
CREATE TABLE delegation_authority(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,manager_subject_id TEXT NOT NULL,capability TEXT NOT NULL CHECK(capability IN('organization.read','organization.write','pii.read','pii.write')),category TEXT NOT NULL CHECK(((category='metadata' AND capability IN('organization.read','organization.write')) OR (category='pii' AND capability IN('pii.read','pii.write')))),scope_kind TEXT NOT NULL CHECK(scope_kind IN('org','employee')),scope_id TEXT NOT NULL,employee_id TEXT,purpose TEXT NOT NULL CHECK(purpose='organization_management'),valid_from TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL CHECK(expires_at>valid_from),mfa_required BOOLEAN NOT NULL,approved_by TEXT NOT NULL,approved_at TIMESTAMPTZ NOT NULL CHECK(approved_at<=valid_from),policy_version TEXT NOT NULL CHECK(length(policy_version) BETWEEN 1 AND 128),UNIQUE(org_id,id),UNIQUE(org_id,id,manager_subject_id,capability,category,purpose),FOREIGN KEY(org_id,manager_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,approved_by) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),CHECK(manager_subject_id<>approved_by),CHECK((scope_kind='org' AND scope_id=org_id AND employee_id IS NULL) OR (scope_kind='employee' AND employee_id IS NOT NULL AND scope_id=employee_id)));
CREATE TABLE access_grant_v2(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,subject_id TEXT NOT NULL,capability TEXT NOT NULL CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage')),category TEXT NOT NULL CHECK(((category='metadata' AND capability IN('organization.read','organization.write') AND purpose='organization_management') OR (category='pii' AND capability IN('pii.read','pii.write') AND purpose='organization_management') OR (category='audit' AND capability='access_grant.manage' AND purpose='security_administration'))),scope_kind TEXT NOT NULL CHECK(scope_kind IN('org','employee')),scope_id TEXT NOT NULL,employee_id TEXT,purpose TEXT NOT NULL CHECK(purpose IN('organization_management','security_administration')),valid_from TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL CHECK(expires_at>valid_from),revoked BOOLEAN NOT NULL DEFAULT false,relation_bound BOOLEAN NOT NULL DEFAULT false CHECK(relation_bound=false),mfa_required BOOLEAN NOT NULL DEFAULT false,revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),authority_id TEXT,issued_by TEXT,issued_at TIMESTAMPTZ,revoked_by TEXT,revoked_at TIMESTAMPTZ,revoke_reason TEXT,UNIQUE(org_id,id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,authority_id,issued_by,capability,category,purpose) REFERENCES delegation_authority(org_id,id,manager_subject_id,capability,category,purpose),FOREIGN KEY(org_id,issued_by) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,revoked_by) REFERENCES subject(org_id,id),CHECK((scope_kind='org' AND scope_id=org_id AND employee_id IS NULL) OR (scope_kind='employee' AND employee_id IS NOT NULL AND scope_id=employee_id)),CHECK((authority_id IS NULL AND issued_by IS NULL AND issued_at IS NULL) OR (authority_id IS NOT NULL AND issued_by IS NOT NULL AND issued_at IS NOT NULL AND issued_by<>subject_id AND capability<>'access_grant.manage')),CHECK((revoked_by IS NULL AND revoked_at IS NULL AND revoke_reason IS NULL) OR (revoked=true AND revoked_by IS NOT NULL AND revoked_at IS NOT NULL AND revoke_reason IS NOT NULL AND revoke_reason IN('access_no_longer_required','policy_change','incorrect_grant'))),CHECK(authority_id IS NULL OR revoked=false OR revoked_by IS NOT NULL),CHECK(issued_at IS NULL OR revoked_at IS NULL OR revoked_at>=issued_at));
INSERT INTO access_grant_v2 SELECT id,org_id,subject_id,capability,category,scope_kind,scope_id,employee_id,purpose,valid_from,expires_at,revoked,relation_bound,mfa_required,1,NULL,NULL,NULL,NULL,NULL,NULL FROM access_grant;
DROP TABLE access_grant;
ALTER TABLE access_grant_v2 RENAME TO access_grant;
CREATE TABLE audit_event_v2(id TEXT PRIMARY KEY,org_id TEXT REFERENCES organization(id),subject_id TEXT,employee_id TEXT,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-05','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-06')),purpose TEXT NOT NULL CHECK(purpose IN('organization_management','security_administration','')),request_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('allowed','denied')),recorded_at TIMESTAMPTZ NOT NULL,grant_id TEXT,FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,grant_id) REFERENCES access_grant(org_id,id),CHECK(subject_id IS NULL OR org_id IS NOT NULL),CHECK(employee_id IS NULL OR org_id IS NOT NULL),CHECK(grant_id IS NULL OR org_id IS NOT NULL),CHECK(outcome<>'denied' OR employee_id IS NULL),CHECK(outcome<>'denied' OR grant_id IS NULL));
INSERT INTO audit_event_v2 SELECT id,org_id,subject_id,employee_id,operation,purpose,request_id,outcome,recorded_at,NULL FROM audit_event;
DROP TABLE audit_event;
ALTER TABLE audit_event_v2 RENAME TO audit_event;
CREATE TABLE grant_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-SEC-02','OP-SEC-03')),key TEXT NOT NULL,digest BYTEA NOT NULL CHECK(octet_length(digest)=32),digest_key_version INTEGER NOT NULL DEFAULT 1 CHECK(digest_key_version=1),result_id TEXT NOT NULL,result_revision BIGINT NOT NULL CHECK(result_revision>0),result_status TEXT NOT NULL CHECK(result_status IN('current','future','expired','revoked')),result_auth_epoch BIGINT NOT NULL CHECK(result_auth_epoch>0),PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,result_id) REFERENCES access_grant(org_id,id));
CREATE INDEX assignment_employee ON capability_assignment(org_id,employee_id);
CREATE INDEX grant_subject_scope ON access_grant(org_id,subject_id,scope_kind,scope_id);
CREATE INDEX grant_employee ON access_grant(org_id,employee_id);
CREATE INDEX grant_authority ON access_grant(org_id,authority_id);
CREATE INDEX grant_issued_by ON access_grant(org_id,issued_by);
CREATE INDEX grant_revoked_by ON access_grant(org_id,revoked_by);
CREATE INDEX authority_manager ON delegation_authority(org_id,manager_subject_id);
CREATE INDEX authority_approver ON delegation_authority(org_id,approved_by);
CREATE INDEX authority_employee ON delegation_authority(org_id,employee_id);
CREATE INDEX grant_receipt_result ON grant_command_receipt(org_id,result_id);
CREATE INDEX audit_subject ON audit_event(org_id,subject_id);
CREATE INDEX audit_employee ON audit_event(org_id,employee_id);
CREATE INDEX audit_grant ON audit_event(org_id,grant_id);
CREATE FUNCTION delegation_authority_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable authority' USING ERRCODE='23514'; END; $$;
CREATE TRIGGER authority_no_update BEFORE UPDATE ON delegation_authority FOR EACH ROW EXECUTE FUNCTION delegation_authority_immutable();
CREATE TRIGGER authority_no_delete BEFORE DELETE ON delegation_authority FOR EACH ROW EXECUTE FUNCTION delegation_authority_immutable();
